import User from "@models/user";
import UserRepository from "@repositories/user_repository";
export class LoginResponse {
    constructor(success, isPasswordCorrect, user = null) {
        this.success = success;
        this.isPasswordCorrect = isPasswordCorrect;
        this.user = user;
    }
    static wrongPassword() { return new LoginResponse(false, false); }
    static userNotFound() { return new LoginResponse(false, true); }
    static success(user) { return new LoginResponse(true, true, user); }
}
export class RegisterResponse {
    constructor(success, isEmailTaken, user = null) {
        this.success = success;
        this.isEmailTaken = isEmailTaken;
        this.user = user;
    }
    static emailTaken() { return new RegisterResponse(false, true); }
    static success(user) { return new RegisterResponse(true, false, user); }
}
export default class UserService {
    constructor() {
        this.repository = new UserRepository();
    }
    get(id) {
        return this.repository.get(id);
    }
    save(user) {
        this.repository.save(user);
    }
    tryLogin(email, password) {
        const user = this.repository.findByEmail(email);
        if (user === null) {
            return LoginResponse.userNotFound();
        }
        if (user.getHashedPassword() !== password) {
            return LoginResponse.wrongPassword();
        }
        return LoginResponse.success(user);
    }
    tryRegister(email, password) {
        const existingUser = this.repository.findByEmail(email);
        if (existingUser) {
            return RegisterResponse.emailTaken();
        }
        const newUser = new User(email, password);
        this.repository.save(newUser);
        return RegisterResponse.success(newUser);
    }
}
