import DataBaseAPI from "@data/data_base_api";
import UserMapper from "@models/user_mapper";
export class LoginResult {
    constructor(userExists, passwordCorrect) {
        this.userExists = userExists;
        this.passwordCorrect = passwordCorrect;
    }
}
export default class UserRepository {
    get(id) {
        const json = DataBaseAPI.getInstance().get("users", id);
        return UserMapper.fromJSON(json);
    }
    save(user) {
        const json = UserMapper.toJSON(user);
        DataBaseAPI.getInstance().save("users", json);
    }
    findByEmail(email) {
        const json = DataBaseAPI.getInstance().findByField("users", "email", email);
        if (json) {
            return UserMapper.fromJSON(json);
        }
        return null;
    }
}
